final class QuickSelectEngine {

    private final int[] values;
    private final int targetIndex;
    private final PivotSelector pivotSelector;
    private int low;
    private int high;

    QuickSelectEngine(int[] values, int targetIndex, PivotSelector pivotSelector) {
        this.values = values;
        this.targetIndex = targetIndex;
        this.pivotSelector = pivotSelector;
        this.low = 0;
        this.high = values.length - 1;
    }

    int select() {
        while (low <= high) {
            int partitionIndex = partitionCurrentRange();

            if (partitionIndex == targetIndex) {
                return values[partitionIndex];
            }

            if (partitionIndex < targetIndex) {
                low = partitionIndex + 1;
            } else {
                high = partitionIndex - 1;
            }
        }

        throw new IllegalStateException("Quickselect failed to locate the target index");
    }

    private int partitionCurrentRange() {
        movePivotToEnd();
        int pivot = values[high];
        int pivotIndex = low;

        for (int i = low; i < high; i++) {
            if (values[i] < pivot) {
                swap(i, pivotIndex);
                pivotIndex++;
            }
        }

        swap(high, pivotIndex);
        return pivotIndex;
    }

    private void movePivotToEnd() {
        swap(pivotSelector.selectPivotIndex(values, low, high), high);
    }

    private void swap(int left, int right) {
        if (left == right) {
            return;
        }

        int temp = values[left];
        values[left] = values[right];
        values[right] = temp;
    }
}

interface PivotSelector {

    int selectPivotIndex(int[] values, int low, int high);
}

enum MedianOfThreePivotSelector implements PivotSelector {
    INSTANCE;

    @Override
    public int selectPivotIndex(int[] values, int low, int high) {
        int mid = low + (high - low) / 2;

        order(values, low, mid);
        order(values, low, high);
        order(values, mid, high);

        return mid;
    }

    private void order(int[] values, int left, int right) {
        if (values[left] > values[right]) {
            int temp = values[left];
            values[left] = values[right];
            values[right] = temp;
        }
    }
}

import java.util.Arrays;

public final class QuickSelect {

    private QuickSelect() {
        // Utility class.
    }

    public static int selectKthSmallest(int[] values, int rank) {
        validateRank(values, rank);
        return selectValidated(Arrays.copyOf(values, values.length), rank);
    }

    public static int selectKthSmallestInPlace(int[] values, int rank) {
        validateRank(values, rank);
        return selectValidated(values, rank);
    }

    public static int kthSmallest(int[] values, int k) {
        return selectKthSmallest(values, k);
    }

    private static int selectValidated(int[] values, int rank) {
        return new QuickSelectEngine(values, rank - 1, MedianOfThreePivotSelector.INSTANCE)
            .select();
    }

    private static void validateRank(int[] values, int rank) {
        if (values == null) {
            throw new IllegalArgumentException("Input array must not be null");
        }

        if (values.length == 0) {
            throw new IllegalArgumentException("Input array must not be empty");
        }

        if (rank < 1 || rank > values.length) {
            throw new IllegalArgumentException(
                "rank must be between 1 and " + values.length + " inclusive");
        }
    }

    public static void main(String[] args) {
        QuickSelectDemo.main(args);
    }
}

